async function requestJSON(url,key,force=false){let cached;try{cached=JSON.parse(localStorage.getItem('baltic-v3-'+key));}catch{}if(!force&&cached&&Date.now()-cached.saved<1800000)return {data:cached.data,saved:cached.saved,stale:false};try{const res=await fetch(url,{signal:AbortSignal.timeout(45000)});if(!res.ok)throw Error('HTTP '+res.status);const data=await res.json();if(data.error)throw Error(data.reason||'Błąd danych');const result={data,saved:Date.now(),stale:false};try{localStorage.setItem('baltic-v3-'+key,JSON.stringify(result));}catch{}return result;}catch(e){if(cached&&Date.now()-cached.saved<21600000)return {...cached,stale:true};throw e;}}
