 html+='<div class="meteo-days" role="row">'+groups.map(d=>`<div class="meteo-day" role="columnheader" style="width:${d.count*48}px"><span>${DAY_TITLE.format(new Date(d.t*1000))}</span></div>`).join('')+'</div>';
