function routeWaveValues(){return ((state.waveSource==='stormglass'?state.stormglassRoute:state.routeWaveGrid)||[]).map(p=>({...p,value:at(p.series,'wave_height'),direction:at(p.series,'wave_direction'),period:at(p.series,'wave_period')}));}
function routeWaveIcon(p){const missing=!valid(p.value),v=missing?'—':format(p.value),title=`Fala znacząca Hs ${v} m · ${fullFmt.format(new Date(selectedEpoch()*1000))} · ${waveSourceLabel()} · ${p.offset===0?'oś trasy':Math.abs(p.offset)+' Mm od osi'} · punkt ${p.lat.toFixed(3)}°N ${p.lon.toFixed(3)}°E`+(valid(p.series?.latitude)&&valid(p.series?.longitude)?` · siatka modelu ${p.series.latitude.toFixed(3)}°N ${p.series.longitude.toFixed(3)}°E`:'')+(routeWaveMeta()?.stale?' · kopia z pamięci':'');return L.divIcon({className:'route-wave-marker',iconSize:[36,22],iconAnchor:[18,11],html:`<span class="route-wave-value ${missing?'missing':''}" data-wave-height="${missing?'':p.value}" title="${title}" aria-label="${title}">${v}</span>`});}
