async function loadField(force=false){if(state.waveSource==='stormglass'&&state.layer==='wave'){await loadStormglassRoute(force);drawField();updateFieldStatus();return;}if(state.model==='smhi_snow'&&state.layer!=='wave'){drawField();updateFieldStatus();return;}if(!state.gridPoints.length)return;const model=state.model,isWave=state.layer==='wave',type=isWave?'wave':model,points=isWave?grid('wave'):state.gridPoints;if(!force&&(isWave?state.waveGrid:state.windGrid[model])){drawField();updateFieldStatus();return;}const pending=++state.fieldLoading;$('fieldStatus').textContent='Pobieranie pola '+(isWave?'ECMWF WAM':MODELS[model].label)+'…';try{const u=url(isWave?'https://marine-api.open-meteo.com/v1/marine':'https://api.open-meteo.com/v1/forecast',points,isWave?{hourly:'wave_height,wave_direction,wave_period',models:WAVE_MODEL,cell_selection:'sea'}:{hourly:'wind_speed_10m,wind_gusts_10m,wind_direction_10m',models:model,wind_speed_unit:'ms',cell_selection:'nearest'});const r=await requestJSON(u,'grid-'+(isWave?WAVE_MODEL:type+'-land-v2'),force);const entries=list(r.data).map((series,i)=>({lat:points[i].lat,lon:points[i].lon,series}));if(isWave)state.waveGrid=entries;else state.windGrid[model]=entries;state.metas['grid-'+type]=r;if(pending===state.fieldLoading){drawField();updateFieldStatus();}}catch(e){if(pending===state.fieldLoading){$('fieldStatus').textContent='Pole mapy niedostępne · użyj ↻, aby ponowić.';drawField();}console.warn('grid',e.message);}}
