function updateScale(){const wave=state.layer==='wave';$('scaleTitle').textContent=wave?'Wysokość fali znaczącej Hs':state.layer==='gust'?'Porywy wiatru':'Prędkość wiatru';$('scaleUnit').textContent=wave?'m':'m/s';$('scaleGradient').style.background=wave?'linear-gradient(90deg,#375486,#269cb6,#48c3a5,#aecb69,#e8b15c,#d06564)':'linear-gradient(90deg,'+[0,3,4,6,10,19,25].map(v=>windHeat(v)+' '+(v/25*100)+'%').join(',')+')';$('scaleLabels').innerHTML=(wave?['0','1','2','3','4','5+']:['0','5','10','15','20','25+']).map(x=>'<span>'+x+'</span>').join('');}
function selectModel(model){if(!MODELS[model])return;state.model=model;document.querySelectorAll('[data-model]').forEach(x=>x.classList.toggle('active',x.dataset.model===model));$('modelDescription').textContent=MODELS[model].desc;renderAll();if(state.layer!=='wave')loadField();}
function renderWaveSource(){const select=$('waveSource');if(select){select.value=state.waveSource;const option=select.querySelector?.('[value="stormglass"]');if(option){option.disabled=!state.stormglassStatus.configured;option.textContent=state.stormglassStatus.configured?(state.stormglassStatus.routeEnabled?'Stormglass AI':'Stormglass AI · porty'):'Stormglass AI · wymagany klucz';}}const note=$('waveSourceNote');if(note)note.textContent=state.waveSource==='stormglass'?(state.stormglassStatus.routeEnabled?'Stormglass AI: porty i punkty na trasie.':'Stormglass AI: wysokość i kierunek fali przy trzech pozycjach portowych na mapie. Pełna siatka trasy jest wyłączona.'):'Fala ECMWF WAM. Stormglass wymaga klucza. SMHI SWAN niepodłączone.';const modelNote=$('waveModelNote');if(modelNote)modelNote.innerHTML='Fala: '+waveSourceLabel()+'.<br>Model nie odwzorowuje osłony portu.';const caption=$('routeSource');if(caption)caption.textContent='Fala Hs w metrach · '+waveSourceLabel();}
async function loadStormglassStatus(){try{const response=await fetch('/api/stormglass/status',{signal:AbortSignal.timeout(12000)});if(!response.ok)throw Error('status');const status=await response.json();state.stormglassStatus={configured:status.configured===true,routeEnabled:status.routeEnabled===true};WAVE_SOURCES.stormglass.available=state.stormglassStatus.configured;}catch{state.stormglassStatus={configured:false,routeEnabled:false};WAVE_SOURCES.stormglass.available=false;}renderWaveSource();}
let stormglassPortRequest,stormglassRouteRequest;
async function loadStormglassPorts(force=false){if(stormglassPortRequest)return stormglassPortRequest;if(!state.stormglassStatus.configured)return;if(state.stormglassWave&&!force){renderAll();return;}state.stormglassLoading=true;state.errors.stormglass='';renderAll();stormglassPortRequest=(async()=>{try{const r=await requestJSON('/api/stormglass/waves?group=ports','stormglass-ports-v1',force);if(!Array.isArray(r.data.records)||r.data.records.length!==PORTS.length)throw Error('Brak danych portów');const records=PORTS.map((p,i)=>r.data.records.find(record=>record.id===String(i)));if(records.some(record=>!record?.hourly))throw Error('Niepełne dane portów');state.stormglassWave=records;state.metas.stormglass={saved:Math.min(...r.data.records.map(x=>x.saved)),stale:r.stale};state.errors.stormglass='';}catch(e){state.errors.stormglass=e.message==='HTTP 429'?'Stormglass: osiągnięto dzienny limit zapytań.':'Stormglass: nie udało się pobrać fal. Sprawdź klucz i odśwież prognozę.';}finally{state.stormglassLoading=false;stormglassPortRequest=null;renderAll();}})();return stormglassPortRequest;}
async function loadStormglassRoute(force=false){if(stormglassRouteRequest)return stormglassRouteRequest;if(!state.stormglassStatus.configured||!state.stormglassStatus.routeEnabled){updateRouteWaves();return;}if(state.stormglassRoute&&!force){updateRouteWaves();return;}stormglassRouteRequest=(async()=>{state.routeWaveLoading=true;state.routeWaveError=false;updateRouteWaves();try{const points=routeGeometry().points,records=[];let offset=0,stale=false;do{const r=await requestJSON('/api/stormglass/waves?group=route&offset='+offset,'stormglass-route-v1-'+offset,force);if(!Array.isArray(r.data.records))throw Error('Brak danych trasy');records.push(...r.data.records);stale=stale||r.stale;offset=r.data.nextOffset;}while(offset!==null);if(records.length!==points.length)throw Error('Niepełna prognoza trasy');state.stormglassRoute=points.map((p,i)=>({...p,series:records.find(r=>r.id===String(i))}));state.metas['route-wave-stormglass']={saved:Math.min(...records.map(r=>r.saved)),stale};}catch{state.routeWaveError=true;}finally{stormglassRouteRequest=null;state.routeWaveLoading=false;updateRouteWaves();if(state.waveSource==='stormglass'&&state.layer==='wave'){drawField();updateFieldStatus();}}})();return stormglassRouteRequest;}

function bindEvents(){ $('waveSource').onchange=e=>{if(!selectWaveSource(e.target.value))e.target.value=state.waveSource;}; $('ports').addEventListener('click',e=>{const b=e.target.closest('[data-port]');if(b)selectPort(Number(b.dataset.port));});$('models').addEventListener('click',e=>{const b=e.target.closest('[data-model]');if(b)selectModel(b.dataset.model);});$('tableLabels').addEventListener('click',e=>{const b=e.target.closest('[data-select-model]');if(b)selectModel(b.dataset.selectModel);});$('routeWaves').onclick=()=>{state.routeWaves=!state.routeWaves;updateRouteWaves();};$('routeFit').onclick=()=>{if(map){const geometry=routeGeometry();map.fitBounds(geometry.polygon.map(p=>[p.lat,p.lon]),{padding:[35,45]});}};$('flags').onclick=()=>{state.flags=!state.flags;$('flags').setAttribute('aria-pressed',state.flags);$('flags').classList.toggle('active',state.flags);updateMarkers();};$('layers').addEventListener('click',e=>{const b=e.target.closest('[data-layer]');if(!b)return;state.layer=b.dataset.layer;document.querySelectorAll('[data-layer]').forEach(x=>x.classList.toggle('active',x===b));updateScale();renderTimeline();updateMarkers();updateRouteWaves();drawField();loadField();});$('ranges').addEventListener('click',e=>{const b=e.target.closest('[data-range]');if(!b)return;state.range=Number(b.dataset.range);document.querySelectorAll('[data-range]').forEach(x=>x.classList.toggle('active',x===b));renderChart();});$('compare').onclick=()=>{state.compare=!state.compare;$('compare').setAttribute('aria-pressed',state.compare);renderChart();};$('hour').oninput=e=>setHour(e.target.value,true);$('chartContent').onclick=e=>{const b=e.target.closest('[data-hour]');if(b)setHour(b.dataset.hour);else if(e.target.closest('svg')){const r=$('chartContent').getBoundingClientRect();setHour(Math.floor((e.clientX-r.left)/48));}};let timer;$('play').onclick=()=>{state.playing=!state.playing;$('play').textContent=state.playing?'Ⅱ':'▶';$('play').setAttribute('aria-pressed',state.playing);$('play').setAttribute('aria-label',state.playing?'Zatrzymaj prognozę':'Odtwórz prognozę');clearInterval(timer);if(state.playing)timer=setInterval(()=>setHour((state.hour+1)%state.times.length,true),1000);};$('now').onclick=()=>{const now=Math.floor(Date.now()/3600000)*3600;const i=state.times.findIndex(t=>t>=now);setHour(i<0?state.times.length-1:i,true);};$('anim').setAttribute('aria-pressed',state.animate);$('anim').classList.toggle('on',state.animate);$('anim').onclick=()=>{state.animate=!state.animate;$('anim').classList.toggle('on',state.animate);$('anim').setAttribute('aria-pressed',state.animate);if(!state.animate&&pctx)pctx.clearRect(0,0,particleCanvas.width,particleCanvas.height);};$('zoomIn').onclick=()=>map?.zoomIn();$('zoomOut').onclick=()=>map?.zoomOut();$('fit').onclick=()=>map?.fitBounds([[54.2,11],[65.7,29]],{padding:[12,12]});$('refresh').onclick=async()=>{$('refresh').disabled=true;await Promise.allSettled([loadPorts(true),loadField(true),loadRouteWaves(true),...(state.waveSource==='stormglass'?[loadStormglassPorts(true)]:[])]);$('refresh').disabled=false;};for(const id of ['info','sources','about'])$(id).onclick=()=>$('aboutDialog').showModal();$('closeDialog').onclick=()=>$('aboutDialog').close();$('aboutDialog').addEventListener('click',e=>{if(e.target===$('aboutDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});document.addEventListener('keydown',e=>{if($('aboutDialog').open||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();setHour(state.hour+(e.key==='ArrowRight'?1:-1),true);}});}
async function start(){state.times=Array.from({length:72},(_,i)=>state.base+i*3600);renderPorts();renderTimeline();renderTableLabels();bindEvents();updateScale();initMap();const clock=()=>$('clock').textContent=timeFmt.format(new Date());clock();setInterval(clock,30000);loadPorts();loadStormglassStatus();try{const r=await fetch('assets/land.json');if(!r.ok)throw Error('land');state.land=await r.json();state.gridPoints=grid();initRouteWaves();await Promise.allSettled([loadField(),loadRouteWaves()]);}catch(e){$('fieldStatus').textContent='Nie można wczytać pola mapy. Odśwież aplikację.';}}
start();
